import { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { io } from "socket.io-client";
import api from "../api";

const socket = io("http://localhost:5000");

function Chat() {
  const userId = Number(localStorage.getItem("userId"));
  const userRole = localStorage.getItem("role"); // "student" | "alumni"
  const [searchParams] = useSearchParams();

  const initialUser = searchParams.get("user")
    ? Number(searchParams.get("user"))
    : null;

  const [messages, setMessages] = useState([]);
  const [contacts, setContacts] = useState([]);
  const [activeUser, setActiveUser] = useState(initialUser);
  const [activeBatch, setActiveBatch] = useState(null);
  const [batch, setBatch] = useState(null);
  const [text, setText] = useState("");
  const [userMap, setUserMap] = useState({});

  /* ================= JOIN SOCKET ================= */
  useEffect(() => {
    if (!userId) return;
    socket.emit("join", userId);
  }, [userId]);

  /* ================= GET ALUMNI BATCH ================= */
  useEffect(() => {
    if (userRole !== "alumni") return;

    api.get("/alumni/me").then((res) => {
      setBatch(res.data.batch);
      socket.emit("join_batch", { batch: res.data.batch });
    });
  }, [userRole]);

  /* ================= LOAD CONTACTS ================= */
  useEffect(() => {
    if (!userId) return;

    api.get(`/chat/contacts/${userId}`)
      .then((res) => {
        setContacts((res.data || []).map(Number));
      })
      .catch(console.error);
  }, [userId]);

  /* ================= FETCH CONTACT NAMES ================= */
  useEffect(() => {
    if (contacts.length === 0) return;

    api.get("/users/by-ids", {
      params: { ids: contacts.join(",") },
    })
    .then((res) => {
      const map = {};
      res.data.forEach((u) => {
        map[Number(u.id)] = u.name;
      });
      setUserMap(map);
    });
  }, [contacts]);

  /* ================= FETCH DM CONVERSATION ================= */
  useEffect(() => {
    if (!activeUser) return;

    setActiveBatch(null);

    api.get("/chat/conversation", {
      params: { user1: userId, user2: activeUser },
    })
    .then((res) => setMessages(res.data || []));
  }, [activeUser, userId]);

  /* ================= FETCH BATCH MESSAGES ================= */
  useEffect(() => {
    if (!activeBatch) return;

    setActiveUser(null);

    api.get(`/chat/batch/${activeBatch}`)
      .then((res) => setMessages(res.data || []));
  }, [activeBatch]);

  /* ================= SOCKET RECEIVE ================= */
  useEffect(() => {
    socket.on("receive_message", (data) => {
      if (activeUser) {
        setMessages((prev) => [...prev, data]);
      }
    });

    socket.on("receive_batch_message", (data) => {
      if (data.batch_id === activeBatch) {
        setMessages((prev) => [...prev, data]);
      }
    });

    return () => {
      socket.off("receive_message");
      socket.off("receive_batch_message");
    };
  }, [activeUser, activeBatch]);

  /* ================= SEND MESSAGE ================= */
  const sendMessage = () => {
    if (!text.trim()) return;

    // Batch message
    if (activeBatch) {
      const payload = {
        sender_id: userId,
        batch_id: activeBatch,
        message_text: text,
      };

      api.post("/chat/batch", payload);
      socket.emit("send_batch_message", payload);

      setMessages((prev) => [...prev, payload]);
      setText("");
      return;
    }

    // DM
    if (!activeUser) return;

    const payload = {
      sender_id: userId,
      receiver_id: activeUser,
      batch_id: null,
      message_text: text,
    };

    api.post("/chat", payload);
    socket.emit("send_message", payload);

    setMessages((prev) => [...prev, payload]);
    setText("");

    if (!contacts.includes(activeUser)) {
      setContacts((prev) => [...prev, activeUser]);
    }
  };

  return (
    <div className="chat-layout">
      {/* ===== SIDEBAR ===== */}
      <aside className="chat-sidebar">
        <h3>Chats</h3>

        {contacts.map((id) => (
          <div
            key={id}
            className={`chat-contact ${activeUser === id ? "active" : ""}`}
            onClick={() => {
              setActiveUser(id);
              setActiveBatch(null);
            }}
          >
            <span className="contact-name">
              {userMap[id] || "Loading..."}
            </span>
          </div>
        ))}

        {/* ===== BATCH GROUP ===== */}
        {userRole === "alumni" && batch && (
          <>
            <h3 style={{ marginTop: 20 }}>Groups</h3>
            <div
              className={`chat-contact ${activeBatch === batch ? "active" : ""}`}
              onClick={() => setActiveBatch(batch)}
            >
              <span className="contact-name">
                Batch {batch}
              </span>
            </div>
          </>
        )}
      </aside>

      {/* ===== CHAT MAIN ===== */}
      <main className="chat-main">
        {!activeUser && !activeBatch ? (
          <div className="chat-empty">Select a chat</div>
        ) : (
          <>
            <div className="chat-header">
              {activeBatch
                ? `Batch ${activeBatch}`
                : userMap[activeUser] || "Chat"}
            </div>

            <div className="chat-messages">
              {messages.map((m, i) => (
                <div
                  key={i}
                  className={`chat-bubble ${
                    m.sender_id === userId ? "sent" : "received"
                  }`}
                >
                  {m.message_text}
                </div>
              ))}
            </div>

            <div className="chat-input">
              <input
                placeholder="Type a message..."
                value={text}
                onChange={(e) => setText(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && sendMessage()}
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

export default Chat;
